# -*- coding: utf-8 -*-
"""
================================================================================
 shahadhi_full_seed.py — بيانات شركة طه الشاحذي الكاملة (ملف واحد مستقل)
================================================================================
 يحتوي هذا الملف على كل البيانات المدمجة + منطق إنشائها.
 يعمل على أي تركيب جديد لـ Frappe v15 + ERPNext v15 + HRMS v15
 (لا يحتاج تطبيق hr_erp — يُنشئ الـ DocTypes المخصصة بنفسه إذا لم توجد)

 التشغيل:
   bench --site <site-name> execute frappe.utils.execute_in_shell --args "['true']"
 أو الأسهل:
   bench --site <site-name> console  ثم:  exec(open('/path/shahadhi_full_seed.py').read())
 أو:
   ضع الملف في apps/  ثم:  bench --site <site> execute <module_path>.run

 ما يتم إنشاؤه:
   - الشركة (الشاحذي) + الحسابات + الأقسام والفروع والمسميات
   - قائمة العطلات SH-عطلات 2026
   - مكونات الرواتب + هيكل SH-هيكل رواتب الشاحذي (مُرسل)
   - 45 موظفاً (SH-HR-EMP-000xx)
   - 45 تعيين راتب (SSA)
   - أنواع دوام متعددة الفترات + التعيينات
   - 440 سجل حضور + 1320 تفصيل فترة
   - 8 قيود رواتب Payroll Entry (يناير–أغسطس 2026)
   - 344 كشف راتب Salary Slip (مُرسلة) — إجمالي 42,857,400 YER
================================================================================
"""
import json
import frappe
from datetime import datetime, date


def _t(v):
    """Parse time string 'HH:MM:SS' to time object"""
    if v is None:
        return None
    if isinstance(v, str):
        parts = [int(p) for p in v.split(":")]
        while len(parts) < 3:
            parts.append(0)
        from datetime import time as _time
        return _time(*parts[:3])
    return v


def _d(v):
    """Parse date string"""
    if isinstance(v, str):
        return datetime.strptime(v[:10], "%Y-%m-%d").date()
    return v


def _exists(dt):
    return frappe.db.exists("DocType", dt)


# ══════════════════════════════════════════════════════════════════
# BOOTSTRAP — إنشاء DocTypes المخصصة إذا لم تكن موجودة (بدون hr_erp)
# ══════════════════════════════════════════════════════════════════

def bootstrap_custom_doctypes():
    print("[1] فحص/إنشاء DocTypes المخصصة...")

    # ── Shift Period (child table) ──
    if not _exists("Shift Period"):
        doc = frappe.get_doc({
            "doctype": "DocType",
            "name": "Shift Period",
            "module": "Custom",
            "istable": 1,
            "custom": 1,
            "autoname": "hash",
            "fields": [
                {"fieldname": "period_number", "label": "رقم الفترة", "fieldtype": "Int", "reqd": 1},
                {"fieldname": "period_name", "label": "اسم الفترة", "fieldtype": "Data"},
                {"fieldname": "start_time", "label": "من", "fieldtype": "Time", "reqd": 1},
                {"fieldname": "end_time", "label": "الى", "fieldtype": "Time", "reqd": 1},
                {"fieldname": "is_break", "label": "استراحة؟", "fieldtype": "Check", "default": 0},
                {"fieldname": "late_grace_period", "label": "سماحية التأخير (دقيقة)", "fieldtype": "Int", "default": 5},
                {"fieldname": "early_exit_grace_period", "label": "سماحية الخروج (دقيقة)", "fieldtype": "Int", "default": 5},
                {"fieldname": "minimum_working_hours", "label": "أدنى ساعات عمل", "fieldtype": "Float", "default": 0},
                {"fieldname": "enable_period_attendance", "label": "تفعيل حضور الفترة", "fieldtype": "Check", "default": 1},
                {"fieldname": "notes", "label": "ملاحظات", "fieldtype": "Small Text"},
            ],
        })
        doc.insert(ignore_permissions=True)
        print("    + Shift Period")

    # ── Attendance Period Detail (child table) ──
    if not _exists("Attendance Period Detail"):
        doc = frappe.get_doc({
            "doctype": "DocType",
            "name": "Attendance Period Detail",
            "module": "Custom",
            "istable": 1,
            "custom": 1,
            "autoname": "hash",
            "fields": [
                {"fieldname": "employee", "label": "الموظف", "fieldtype": "Link", "options": "Employee"},
                {"fieldname": "attendance", "label": "الحضور", "fieldtype": "Link", "options": "Attendance"},
                {"fieldname": "shift_type", "label": "نوع الدوام", "fieldtype": "Link", "options": "Shift Type"},
                {"fieldname": "period_number", "label": "رقم الفترة", "fieldtype": "Int"},
                {"fieldname": "period_name", "label": "الفترة", "fieldtype": "Data"},
                {"fieldname": "period_start", "label": "بداية الفترة", "fieldtype": "Datetime"},
                {"fieldname": "period_end", "label": "نهاية الفترة", "fieldtype": "Datetime"},
                {"fieldname": "actual_check_in", "label": "الحضور فعلياً", "fieldtype": "Datetime"},
                {"fieldname": "actual_check_out", "label": "الانصراف فعلياً", "fieldtype": "Datetime"},
                {"fieldname": "period_status", "label": "الحالة", "fieldtype": "Select",
                 "options": "Present\nAbsent\nLate\nHalf Day\nNot Marked\nBreak Skip\nBreak"},
                {"fieldname": "working_hours", "label": "ساعات العمل", "fieldtype": "Float"},
                {"fieldname": "late_minutes", "label": "دقائق التأخير", "fieldtype": "Float"},
                {"fieldname": "early_exit_minutes", "label": "دقائق الخروج المبكر", "fieldtype": "Float"},
                {"fieldname": "absent_hours", "label": "ساعات الغياب", "fieldtype": "Float"},
                {"fieldname": "overtime_hours", "label": "ساعات إضافية", "fieldtype": "Float"},
            ],
        })
        doc.insert(ignore_permissions=True)
        print("    + Attendance Period Detail")

    # ── ensure period_status options include every value used by the data ──
    if _exists("Attendance Period Detail"):
        opts = "Present\nAbsent\nLate\nHalf Day\nNot Marked\nBreak Skip\nBreak"
        dt = frappe.get_doc("DocType", "Attendance Period Detail")
        for f in dt.fields:
            if f.fieldname == "period_status" and f.options != opts:
                f.options = opts
                dt.save(ignore_permissions=True)
                print("    ~ updated period_status options")
                break

    # ── Custom Fields ──
    def ensure_cf(dt, fieldname, label, fieldtype, options=None, insert_after=None, default=None):
        if frappe.db.exists("Custom Field", {"dt": dt, "fieldname": fieldname}):
            return
        cf = frappe.get_doc({
            "doctype": "Custom Field",
            "dt": dt,
            "fieldname": fieldname,
            "label": label,
            "fieldtype": fieldtype,
            "options": options,
            "insert_after": insert_after or "naming_series",
            "default": default,
        })
        cf.save(ignore_permissions=True)

    ensure_cf("Shift Type", "enable_multi_period", "تفعيل الدوام متعدد الفترات", "Check")
    ensure_cf("Shift Type", "shift_periods", "الفترات", "Table", options="Shift Period",
              insert_after="enable_multi_period")
    ensure_cf("Attendance", "attendance_period_details", "تفاصيل فترات الدوام", "Table",
              options="Attendance Period Detail", insert_after="working_hours")

    frappe.db.commit()
    print("    ✓ جاهز")


# ══════════════════════════════════════════════════════════════════
# COMPANY + ACCOUNTS
# ══════════════════════════════════════════════════════════════════

COMPANY = "الشاحذي"
ABBR = "sh"
CURRENCY = "YER"

# ضريبة الدخل 15% على إجمالي الاستحقاقات
TAX_COMPONENT = "ضريبة الدخل"
TAX_FORMULA = "(BAS + TRN + RISK + NAT + HOU) * 0.15"


def seed_company(D):
    print("[2] الشركة والحسابات...")
    # ensure standard Warehouse Types exist (missing on some fresh installs)
    for wt in ["Transit", "Manufacturing", "Receiving", "Finished Goods",
               "Store", "Raw Material"]:
        if frappe.db.exists("DocType", "Warehouse Type") and \
           not frappe.db.exists("Warehouse Type", wt):
            try:
                frappe.get_doc({"doctype": "Warehouse Type", "__newname": wt,
                                "warehouse_type": wt}).insert(ignore_permissions=True)
            except Exception:
                pass
    if not frappe.db.exists("Company", COMPANY):
        comp = frappe.get_doc({
            "doctype": "Company",
            "company_name": D["company"]["company_name"] or COMPANY,
            "abbr": ABBR,
            "default_currency": CURRENCY,
            "country": "Yemen",
            "company_email": "info@example.com",
        })
        comp.insert(ignore_permissions=True)
        frappe.db.commit()
        print(f"    + شركة {COMPANY}")
    else:
        print("    ✓ الشركة موجودة")

    comp = frappe.get_doc("Company", COMPANY)

    # Cash account
    cash = comp.default_cash_account
    if not cash:
        cash = frappe.db.get_value("Account",
            {"company": COMPANY, "account_type": "Cash", "is_group": 0}, "name")
    if not cash:
        parent = frappe.db.get_value("Account",
            {"company": COMPANY, "account_name": ["like", "%Cash%"], "is_group": 1}, "name") \
            or frappe.db.get_value("Account",
                {"company": COMPANY, "root_type": "Asset", "is_group": 1}, "name")
        acc = frappe.get_doc({
            "doctype": "Account", "company": COMPANY, "account_name": "نقد",
            "account_type": "Cash", "parent_account": parent, "currency": CURRENCY,
        })
        acc.insert(ignore_permissions=True)
        cash = acc.name
    print(f"    حساب النقد: {cash}")

    # Payroll payable account
    payable = frappe.db.get_value("Account",
        {"company": COMPANY, "account_name": ["like", "%رواتب واجبة%"], "is_group": 0}, "name")
    if not payable:
        payable = frappe.db.get_value("Account",
            {"company": COMPANY, "account_name": ["like", "%Payroll Payable%"],
             "account_type": "Payroll Payable", "is_group": 0}, "name")
    if not payable:
        parent = frappe.db.get_value("Account",
            {"company": COMPANY, "root_type": "Liability", "is_group": 1}, "name")
        acc = frappe.get_doc({
            "doctype": "Account", "company": COMPANY,
            "account_name": "رواتب واجبة الدفع",
            "parent_account": parent,
            "currency": CURRENCY,
        })
        acc.insert(ignore_permissions=True)
        payable = acc.name
    # payroll payable must have NO account type (HRMS validation)
    if frappe.db.get_value("Account", payable, "account_type"):
        frappe.db.set_value("Account", payable, "account_type", None)
    print(f"    حساب الرواتب الواجبة: {payable}")

    company_fields = {"default_cash_account": cash, "default_bank_account": cash}
    if frappe.get_meta("Company").has_field("default_payroll_payable_account"):
        company_fields["default_payroll_payable_account"] = payable
    frappe.db.set_value("Company", COMPANY, company_fields)
    frappe.db.commit()

    # Mode of payment نقد
    if not frappe.db.exists("Mode of Payment", "نقد"):
        mop = frappe.get_doc({
            "doctype": "Mode of Payment", "mode_of_payment": "نقد", "enabled": 1,
            "type": "Cash", "accounts": [{"company": COMPANY, "default_account": cash}],
        })
        mop.insert(ignore_permissions=True)
        print("    + طريقة دفع: نقد")

    return {"cash": cash, "payable": payable}


def seed_org_structure(D):
    print("[3] الأقسام والفروع والمسميات...")
    for dep in D.get("departments", []):
        dn = dep["department_name"]
        if not frappe.db.exists("Department", dn):
            try:
                frappe.get_doc({"doctype": "Department", "department_name": dn,
                                "company": COMPANY}).insert(ignore_permissions=True)
            except Exception:
                pass
    for br in D.get("branches", []):
        bn = br["branch"].replace(f" - {ABBR}", "")
        if not frappe.db.exists("Branch", bn):
            try:
                frappe.get_doc({"doctype": "Branch", "branch": bn}).insert(ignore_permissions=True)
            except Exception:
                pass
    desigs = set()
    for e in D.get("employees", []):
        if e.get("designation"):
            desigs.add(e["designation"])
    for dg in sorted(desigs):
        if not frappe.db.exists("Designation", dg):
            try:
                frappe.get_doc({"doctype": "Designation", "designation_name": dg})\
                    .insert(ignore_permissions=True)
            except Exception:
                pass
    etypes = set(e.get("employment_type") for e in D.get("employees", []) if e.get("employment_type"))
    for et in sorted(etypes):
        if et and not frappe.db.exists("Employment Type", et):
            try:
                frappe.get_doc({"doctype": "Employment Type", "employee_type_name": et})\
                    .insert(ignore_permissions=True)
            except Exception:
                pass
    frappe.db.commit()
    print("    ✓ هيكل تنظيمي")


def seed_holidays(D):
    print("[4] قائمة العطلات...")
    for hl in D.get("holiday_lists", []):
        if frappe.db.exists("Holiday List", hl["name"]):
            continue
        doc = frappe.get_doc({
            "doctype": "Holiday List",
            "holiday_list_name": hl.get("holiday_list_name") or hl["name"],
            "from_date": hl["from_date"],
            "to_date": hl["to_date"],
            "weekly_off": hl.get("weekly_off"),
        })
        for h in hl.get("holidays", []):
            doc.append("holidays", {
                "holiday_date": h["holiday_date"],
                "description": h["description"],
                "weekly_off": h.get("weekly_off", 0),
            })
        doc.insert(ignore_permissions=True)
        print(f"    + {doc.name}")
    frappe.db.set_value("Company", COMPANY, "default_holiday_list",
                        D["holiday_lists"][0]["name"] if D.get("holiday_lists") else None)
    frappe.db.commit()


def seed_fiscal_years():
    print("[4b] السنوات المالية...")
    for y in (2025, 2026):
        if frappe.db.exists("Fiscal Year", str(y)):
            continue
        try:
            frappe.get_doc({
                "doctype": "Fiscal Year",
                "year": str(y),
                "__newname": str(y),
                "year_start_date": f"{y}-01-01",
                "year_end_date": f"{y}-12-31",
            }).insert(ignore_permissions=True)
            print(f"    + FY {y}")
        except Exception as ex:
            print(f"    ! FY {y}: {repr(ex)[:120]}")
    frappe.db.commit()


def seed_salary_components(D):
    print("[5] مكونات الرواتب...")
    abbr_map = {"الراتب الأساسي": "BAS", "بدل مواصلات": "TRN", "بدل مخاطر": "RISK",
                "بدل طبيعه عمل": "NAT", "بدل سكن": "HOU", "بدل طبيعة العمل": "MEA"}
    ded_comps = set()
    needed = set()
    for ss in D.get("salary_structures", []):
        for row in ss.get("earnings", []):
            needed.add(row["salary_component"])
        for row in ss.get("deductions", []):
            needed.add(row["salary_component"])
            ded_comps.add(row["salary_component"])
    needed.add(TAX_COMPONENT)
    ded_comps.add(TAX_COMPONENT)
    for c in sorted(needed):
        if not frappe.db.exists("Salary Component", c):
            frappe.get_doc({
                "doctype": "Salary Component",
                "salary_component": c,
                "salary_component_abbr": abbr_map.get(
                    c, "TAX" if c == TAX_COMPONENT else c[:3].upper()),
                "type": "Deduction" if c in ded_comps else "Earning",
            }).insert(ignore_permissions=True)
            print(f"    + {c}")
        else:
            frappe.db.set_value("Salary Component", c, "type",
                                "Deduction" if c in ded_comps else "Earning")
    frappe.db.set_value("Salary Component", TAX_COMPONENT,
                        "depends_on_payment_days", 0)
    frappe.db.commit()


def seed_salary_structures(D, accounts):
    print("[6] هياكل الرواتب...")
    for ss in D.get("salary_structures", []):
        if frappe.db.exists("Salary Structure", ss["name"]):
            print(f"    ✓ {ss['name']} موجود")
            continue
        doc = frappe.get_doc({
            "doctype": "Salary Structure",
            "__newname": ss["name"],
            "name": ss["name"],
            "company": COMPANY,
            "is_active": "Yes",
            "currency": CURRENCY,
            "payroll_frequency": "Monthly",
            "mode_of_payment": "نقد",
        })
        for e in ss.get("earnings", []):
            doc.append("earnings", {
                "salary_component": e["salary_component"],
                "abbr": e.get("abbr"),
                "amount_based_on_formula": e.get("amount_based_on_formula"),
                "formula": e.get("formula"),
                "depends_on_payment_days": e.get("depends_on_payment_days", 0),
            })
        data_deds = ss.get("deductions", []) or []
        names = {d.get("salary_component") for d in data_deds}
        if TAX_COMPONENT not in names:
            doc.append("deductions", {
                "salary_component": TAX_COMPONENT,
                "abbr": "TAX",
                "amount_based_on_formula": 1,
                "formula": TAX_FORMULA,
                "depends_on_payment_days": 0,
            })
        for drow in data_deds:
            payload = {
                "salary_component": drow["salary_component"],
                "abbr": drow.get("abbr"),
                "amount_based_on_formula": drow.get(
                    "amount_based_on_formula"),
                "formula": drow.get("formula"),
                "depends_on_payment_days": 0,
            }
            if not drow.get("amount_based_on_formula"):
                payload["amount"] = drow.get("amount", 0)
            doc.append("deductions", payload)
        doc.insert(ignore_permissions=True)
        doc.submit()
        print(f"    + {ss['name']} (مُرسل)")
    frappe.db.commit()


def seed_employees(D):
    print("[7] الموظفين...")
    genders = set(e.get("gender") for e in D["employees"] if e.get("gender"))
    genders.update({"Male", "Female", "Other"})
    for g in sorted(genders):
        if not frappe.db.exists("Gender", g):
            try:
                frappe.get_doc({"doctype": "Gender", "__newname": g,
                                "gender": g}).insert(ignore_permissions=True)
            except Exception:
                pass
    emp_map = {}
    for e in D["employees"]:
        target_id = e["name"]
        existing = frappe.db.exists("Employee", target_id)
        if existing:
            emp_map[target_id] = target_id
            continue
        payload = {
            "doctype": "Employee",
            "first_name": e.get("first_name") or e["employee_name"],
            "employee_name": e["employee_name"],
            "gender": e.get("gender") or "Male",
            "date_of_birth": e.get("date_of_birth") or "1990-01-01",
            "date_of_joining": e["date_of_joining"],
            "status": e.get("status") or "Active",
            "cell_number": e.get("cell_number"),
            "department": e.get("department"),
            "branch": e.get("branch"),
            "designation": e.get("designation"),
            "employment_type": e.get("employment_type"),
            "holiday_list": e.get("holiday_list") or (
                D["holiday_lists"][0]["name"] if D.get("holiday_lists") else None),
            "company": COMPANY,
        }
        payload = {k: v for k, v in payload.items() if v}
        doc = frappe.get_doc(payload)
        doc.insert(ignore_permissions=True)
        actual = doc.name
        if actual != target_id:
            try:
                frappe.rename_doc("Employee", actual, target_id, force=True)
                actual = target_id
            except Exception as ex:
                print(f"    ! rename {actual} -> {target_id}: {repr(ex)[:120]}")
        emp_map[e["name"]] = actual
    frappe.db.commit()
    print(f"    ✓ {len(emp_map)} موظف")
    return emp_map


def seed_ssas(D, emp_map, accounts):
    print("[8] تعيينات هياكل الرواتب...")
    n = 0
    join_map = {e["name"]: e.get("date_of_joining") for e in D["employees"]}
    for ssa in D.get("ssas", []):
        emp = emp_map[ssa["employee"]]
        exists = frappe.db.exists("Salary Structure Assignment", {
            "employee": emp, "salary_structure": ssa["salary_structure"]})
        if exists:
            continue
        fd = ssa["from_date"]
        jd = join_map.get(ssa["employee"])
        if jd and jd > fd:
            fd = jd  # SSA cannot precede joining date
        doc = frappe.get_doc({
            "doctype": "Salary Structure Assignment",
            "employee": emp,
            "employee_name": frappe.db.get_value("Employee", emp, "employee_name"),
            "salary_structure": ssa["salary_structure"],
            "from_date": fd,
            "base": ssa["base"],
            "variable": ssa.get("variable", 0),
            "currency": CURRENCY,
            "payroll_payable_account": accounts["payable"],
        })
        doc.insert(ignore_permissions=True)
        doc.submit()
        n += 1
    frappe.db.commit()
    print(f"    + {n} تعيين راتب")


def seed_shifts(D, emp_map):
    print("[9] أنواع الدوام والفترات والتعيينات...")
    shift_map = {}
    for st in D.get("shift_types", []):
        if frappe.db.exists("Shift Type", st["name"]):
            shift_map[st["name"]] = st["name"]
            continue
        doc = frappe.get_doc({
            "doctype": "Shift Type",
            "__newname": st["name"],
            "name": st["name"],
            "start_time": _t(st["start_time"]),
            "end_time": _t(st["end_time"]),
            "enable_multi_period": st.get("enable_multi_period"),
            "late_entry_grace_period": st.get("late_entry_grace_period"),
            "early_exit_grace_period": st.get("early_exit_grace_period"),
        })
        for p in st.get("shift_periods", []):
            doc.append("shift_periods", {
                "period_number": p["period_number"],
                "period_name": p.get("period_name"),
                "start_time": _t(p["start_time"]),
                "end_time": _t(p["end_time"]),
                "is_break": p.get("is_break"),
                "late_grace_period": p.get("late_grace_period"),
                "early_exit_grace_period": p.get("early_exit_grace_period"),
                "minimum_working_hours": p.get("minimum_working_hours"),
                "enable_period_attendance": p.get("enable_period_attendance"),
                "notes": p.get("notes"),
            })
        doc.insert(ignore_permissions=True)
        shift_map[st["name"]] = st["name"]
    frappe.db.commit()
    print(f"    ✓ {len(shift_map)} نوع دوام")

    n = 0
    for sa in D.get("shift_assignments", []):
        emp = emp_map.get(sa["employee"])
        stype = shift_map.get(sa["shift_type"])
        if not emp or not stype:
            continue
        exists = frappe.db.exists("Shift Assignment", {
            "employee": emp, "shift_type": stype, "start_date": sa["start_date"]})
        if exists:
            continue
        try:
            doc = frappe.get_doc({
                "doctype": "Shift Assignment",
                "employee": emp,
                "company": COMPANY,
                "shift_type": stype,
                "start_date": sa["start_date"],
                "end_date": sa.get("end_date"),
                "status": sa.get("status", "Active"),
            })
            doc.insert(ignore_permissions=True)
            doc.submit()
            n += 1
        except Exception:
            frappe.clear_messages()
    frappe.db.commit()
    print(f"    + {n} تعيين دوام")
    return shift_map


def seed_attendance(D, emp_map, shift_map):
    print("[10] الحضور وتفاصيل الفترات...")
    existing_dates = {}
    for a in frappe.get_all("Attendance",
            filters={"employee": ["in", list(emp_map.values())]},
            fields=["name", "employee", "attendance_date"]):
        existing_dates[(a.employee, str(a.attendance_date))] = a.name
    n = 0
    npd = 0
    for a in D.get("attendance", []):
        emp = emp_map[a["employee"]]
        key = (emp, a["attendance_date"])
        att_id = existing_dates.get(key)
        if att_id:
            # still attach period details if missing
            cnt = frappe.db.count("Attendance Period Detail",
                                  {"parent": att_id, "parenttype": "Attendance"})
            rows = a.get("period_details", [])
            if cnt == 0 and rows:
                adoc = frappe.get_doc("Attendance", att_id)
                for pd in rows:
                    adoc.append("attendance_period_details", _pd_row(pd, emp))
                adoc.save(ignore_permissions=True)
                npd += len(rows)
            continue
        try:
            doc = frappe.get_doc({
                "doctype": "Attendance",
                "employee": emp,
                "employee_name": frappe.db.get_value("Employee", emp, "employee_name"),
                "company": COMPANY,
                "attendance_date": a["attendance_date"],
                "status": a["status"],
                "shift": shift_map.get(a.get("shift")) or a.get("shift"),
                "in_time": a.get("in_time"),
                "out_time": a.get("out_time"),
                "working_hours": a.get("working_hours"),
                "late_entry": a.get("late_entry"),
                "early_exit": a.get("early_exit"),
                "docstatus": a.get("docstatus", 1),
            })
            for pd in a.get("period_details", []):
                doc.append("attendance_period_details", _pd_row(pd, emp))
                npd += 1
            doc.flags.ignore_validate = True
            doc.insert(ignore_permissions=True)
            n += 1
        except Exception as ex:
            frappe.clear_messages()
            print(f"    ! خطأ {emp} {a['attendance_date']}: {ex}")
    frappe.db.commit()
    print(f"    + {n} حضور / {npd} تفصيل فترة")


def _pd_row(pd, emp):
    return {
        "employee": emp,
        "period_number": pd.get("period_number"),
        "period_name": pd.get("period_name"),
        "period_start": pd.get("period_start"),
        "period_end": pd.get("period_end"),
        "actual_check_in": pd.get("actual_check_in"),
        "actual_check_out": pd.get("actual_check_out"),
        "period_status": pd.get("period_status"),
        "working_hours": pd.get("working_hours"),
        "late_minutes": pd.get("late_minutes"),
        "early_exit_minutes": pd.get("early_exit_minutes"),
        "absent_hours": pd.get("absent_hours"),
        "overtime_hours": pd.get("overtime_hours"),
    }


def seed_payroll(D, emp_map, accounts):
    print("[11] قيود الرواتب وكشوف المرتبات...")
    pe_map = {}
    for pe in D.get("payroll_entries", []):
        old_name = pe["name"]
        existing = frappe.db.exists("Payroll Entry",
            {"company": COMPANY, "start_date": pe["start_date"], "docstatus": ["<", 2]})
        if existing:
            pe_map[old_name] = existing
            continue
        doc = frappe.get_doc({
            "doctype": "Payroll Entry",
            "company": COMPANY,
            "cost_center": pe.get("cost_center") or frappe.db.get_value(
                "Cost Center", {"company": COMPANY, "is_group": 0}),
            "department": frappe.db.get_value("Department", pe.get("department"), "name")
                          if pe.get("department") else None,
            "branch": frappe.db.get_value("Branch", pe.get("branch"), "name")
                      if pe.get("branch") else None,
            "start_date": pe["start_date"],
            "end_date": pe["end_date"],
            "payroll_frequency": "Monthly",
            "currency": CURRENCY,
            "exchange_rate": pe.get("exchange_rate", 1.0),
            "payroll_payable_account": accounts["payable"],
            "payment_account": accounts["cash"],
            "posting_date": pe.get("posting_date"),
        })
        for erow in pe.get("employees", []):
            emp = emp_map.get(erow["employee"])
            if emp:
                doc.append("employees", {"employee": emp})
        doc.insert(ignore_permissions=True)
        doc.submit()
        pe_map[old_name] = doc.name
    frappe.db.commit()
    print(f"    ✓ {len(pe_map)} قيد رواتب")

    n = 0
    ns = 0
    for slip in D.get("salary_slips", []):
        emp = emp_map[slip["employee"]]
        exists = frappe.db.exists("Salary Slip", {
            "employee": emp, "start_date": slip["start_date"]})
        if exists:
            continue
        try:
            doc = frappe.get_doc({
                "doctype": "Salary Slip",
                "employee": emp,
                "company": COMPANY,
                "start_date": slip["start_date"],
                "end_date": slip["end_date"],
                "posting_date": slip.get("posting_date"),
                "salary_structure": slip["salary_structure"],
                "currency": CURRENCY,
                "payroll_entry": pe_map.get(slip.get("payroll_entry")),
                "mode_of_payment": "نقد",
            })
            doc.insert(ignore_permissions=True)
            doc.submit()
            n += 1
            if doc.docstatus == 1:
                ns += 1
        except Exception as ex:
            frappe.clear_messages()
            print(f"    ! خطأ كشف {emp} {slip['start_date']}: {ex}")
        if n % 50 == 0 and n > 0:
            frappe.db.commit()
    # update PE counts
    for old, new in pe_map.items():
        cnt_c = frappe.db.count("Salary Slip", {"payroll_entry": new})
        cnt_s = frappe.db.count("Salary Slip", {"payroll_entry": new, "docstatus": 1})
        frappe.db.set_value("Payroll Entry", new,
            {"salary_slips_created": cnt_c, "salary_slips_submitted": cnt_s})
    frappe.db.commit()
    print(f"    + {n} كشف راتب ({ns} مُرسلة)")


# ══════════════════════════════════════════════════════════════════
# MAIN
# ══════════════════════════════════════════════════════════════════

def run():
    t0 = datetime.now()
    print("=" * 60)
    print(" بيانات شركة طه الشاحذي — التثبيت الكامل")
    print("=" * 60)
    D = DATA

    bootstrap_custom_doctypes()
    accounts = seed_company(D)
    seed_org_structure(D)
    seed_holidays(D)
    seed_fiscal_years()
    seed_salary_components(D)
    seed_salary_structures(D, accounts)
    emp_map = seed_employees(D)
    seed_ssas(D, emp_map, accounts)
    shift_map = seed_shifts(D, emp_map)
    seed_attendance(D, emp_map, shift_map)
    seed_payroll(D, emp_map, accounts)

    print("\n" + "=" * 60)
    print(" ملخص التحقق:")
    for dt, filters in [
        ("Employee", {"company": COMPANY}),
        ("Salary Structure Assignment", {"salary_structure": "SH-هيكل رواتب الشاحذي"}),
        ("Shift Type", {"name": ["like", "SH-%"]}),
        ("Shift Assignment", {"company": COMPANY}),
        ("Attendance", {}),
        ("Payroll Entry", {"company": COMPANY, "docstatus": 1}),
        ("Salary Slip", {"company": COMPANY, "docstatus": 1}),
    ]:
        print(f"   {dt}: {frappe.db.count(dt, filters)}")
    tot = frappe.db.sql("""SELECT SUM(net_pay) FROM `tabSalary Slip`
                           WHERE company=%s AND docstatus=1""", COMPANY)[0][0] or 0
    print(f"   إجمالي صافي المرتبات: {tot:,.0f} YER")
    print("=" * 60)
    print(f" انتهى في {(datetime.now() - t0).seconds} ثانية")




